import { describe, expect, it, vi } from "vitest"
import { artifactCopyMove, chatArtifactContext, chatArtifactProjects, chatCraftLease, documentReviewActions } from "@/lib/feature-flags"
import { execFileSync } from "node:child_process"
import { readFileSync } from "node:fs"
import path from "node:path"

// Every /api/v1 path the web app calls must be a route the server registers
// (internal/api/openapi.gen.json, regenerated by `go run ./cmd/gen-openapi`).
// Oponentura 19 Oct: candidate14 shipped a Document history panel whose two
// endpoints lived in an unmerged PR; component tests were green because they
// mock fetch. A clean merge is not a working feature.

const ROOT = path.resolve(__dirname, "../..")

// Paths this check cannot resolve statically, each with the reason. The list
// lives here, at the base of the Harbor 2 stack, for every area branch; an
// entry a branch does not use yet is harmless.
const KNOWN: Record<string, string> = {
  "/api/v1": "base prefix in a matcher, not a call",
  "/api/v1/admin": "prefix test in workspace-availability",
  "/api/v1/me": "prefix test in workspace-availability",
  "/api/v1/auth/config": "method allowlist entry in workspace-availability, not a call",
  "/api/v1/admin/instance": "base of /admin/instance/… paths built by concatenation",
  "/api/v1/admin/instance/backups": "base of /admin/instance/backups/… paths built by concatenation",
  "/api/v1/agents//files": "comment describing the empty-id request it prevents",
  "/api/v1/X": "intake and issue detail join a caller-built tail",
  "/api/v1/X/memory": "memory workspace picks crews|agents at run time",
  "/api/v1/chats/X": "restricted memory joins a caller-built tail",
  "/api/v1/chats/X/Xs": "e2 cards pick the collection name at run time",
  "/api/v1/consolidate/proposed/X/X": "approve|reject chosen at run time",
  "/api/v1/skills/proposed/X": "approve|reject chosen at run time",
  "/api/v1/crews/X/X": "crew environment picks the action at run time",
  "/api/v1/crews/X/container-": "container-start|stop|restart built by concatenation",
  "/api/v1/users/me/X": "memory workspace picks the collection at run time",
  "/api/v1/workspaces/X/pipelines/X/X": "routine action chosen at run time",
  "/api/v1/workspaces/X/skills/X/X": "skill action chosen at run time",
  "/api/v1/admin/users/X/X": "person sessions pick the tail (sessions, revoke) at run time",
  "/api/v1/workspaces/X/X": "invite picks invitations or members/provision at run time",
  "/api/v1/hooks/X/X": "enable or disable chosen at run time",
  "/api/v1/llm/models": "known defect #3766: the chat model picker calls a route nobody registers",
}

// Proposed clients may ship behind a default-off surface before their API.
// Scope each exception to its exact client file: the same missing path used by
// another component must still fail. These are not registered server routes.
const DEFERRED_CLIENTS: Record<string, { file: string; flag: string; enabled: () => boolean }> = {
  "/api/v1/chats/X/X": { file: "components/features/chat/artifact-context/client.ts", flag: "NEXT_PUBLIC_CHAT_ARTIFACT_CONTEXT", enabled: chatArtifactContext },
  // Artifact project routes: pending backend, agent B follow-up to PR #4356.
  "/api/v1/pages/artifacts/availability": { file: "components/features/chat/artifact-context/projects/client.ts", flag: "NEXT_PUBLIC_CHAT_ARTIFACT_PROJECTS", enabled: chatArtifactProjects },
  "/api/v1/pages/X/artifact": { file: "components/features/chat/artifact-context/projects/client.ts", flag: "NEXT_PUBLIC_CHAT_ARTIFACT_PROJECTS", enabled: chatArtifactProjects },
  // Craft lease routes: pending backend, the EditLease HTTP proposal.
  "/api/v1/pages/X/craft": { file: "components/features/chat/artifact-context/craft/lease-client.ts", flag: "NEXT_PUBLIC_CHAT_CRAFT_LEASE", enabled: chatCraftLease },
  "/api/v1/pages/X/document/proposals": { file: "lib/documents/proposals.ts", flag: "NEXT_PUBLIC_DOCUMENT_REVIEW_ACTIONS", enabled: documentReviewActions },
  "/api/v1/pages/X/duplicate": { file: "lib/pages/catalog-duplicate.ts", flag: "NEXT_PUBLIC_ARTIFACT_COPY_MOVE", enabled: artifactCopyMove },
  "/api/v1/pages/X/move": { file: "lib/pages/catalog-move.ts", flag: "NEXT_PUBLIC_ARTIFACT_COPY_MOVE", enabled: artifactCopyMove },
}

function routes(): RegExp[] {
  const spec = JSON.parse(readFileSync(path.join(ROOT, "internal/api/openapi.gen.json"), "utf8")) as { paths: Record<string, unknown> }
  return Object.keys(spec.paths).map((p) => new RegExp(`^${p.replace(/[.*+?^$()|[\]\\]/g, "\\$&").replace(/\{[^}]+\}/g, "[^/]+")}${"$"}`))
}

function calledPaths(out = execFileSync("git", ["grep", "-nE", "/api/v1/", "--", "app", "components", "hooks", "lib", ":!**/__tests__/**", ":!**/*.test.*"], { cwd: ROOT, encoding: "utf8" })): Iterable<[string, string]> {
  const found = new Map<string, [string, string]>()
  for (const line of out.split("\n")) {
    const file = line.split(":", 1)[0]
    // Fold template holes innermost first, so `/pages/${encode(`@${id}`)}/x`
    // reads as /pages/§/x.
    let text = line
    for (let prev = ""; prev !== text; ) {
      prev = text
      text = text.replace(/\$\{[^{}]*\}/g, "§")
    }
    for (const m of text.matchAll(/[`"'](\/api\/v1\/[^`"'\s]*)/g)) {
      const raw = m[1]
      let u = raw.split("?")[0].split("#")[0]
      u = u.replace(/(?<!\/)§.*$/, "") // a hole glued to a segment is a query suffix
      u = u.replace(/§/g, "X")
      if (u.includes("${") || u.includes("*") || u.includes("...")) continue
      const normalized = u.replace(/\/$/, "")
      const where = `${file}${raw.endsWith("/") ? " (prefix)" : ""}`
      found.set(JSON.stringify([normalized, where]), [normalized, where])
    }
  }
  return found.values()
}

function missingRoutes(calls: Iterable<[string, string]>, rs = routes()): string[] {
  const prefixes = rs.map((r) => new RegExp(r.source.replace(/\$$/, "")))
  const missing: string[] = []
  for (const [u, where] of calls) {
    if (KNOWN[u] || DEFERRED_CLIENTS[u]?.file === where) continue
    if (rs.some((r) => r.test(u.replace(/X/g, "x")))) continue
    if (where.endsWith("(prefix)") && prefixes.some((r) => r.test(`${u.replace(/X/g, "x")}/`))) continue
    missing.push(`${u} (${where.replace(" (prefix)", "")})`)
  }
  return missing
}

describe("frontend → router", () => {
  it("proposed clients remain limited to default-off surfaces", () => {
    try {
      for (const client of Object.values(DEFERRED_CLIENTS)) {
        vi.stubEnv(client.flag, undefined)
        expect(client.enabled(), client.file).toBe(false)
        vi.stubEnv(client.flag, "false")
        expect(client.enabled(), client.file).toBe(false)
      }
    } finally {
      vi.unstubAllEnvs()
    }
  })

  it.each(Object.entries(DEFERRED_CLIENTS))("does not hide another file using deferred path %s", (url, client) => {
    const deferred = `${client.file}:1:apiFetch("${url}")`
    const unflagged = `components/unflagged-client.tsx:1:apiFetch("${url}")`
    const expected = [`${url} (components/unflagged-client.tsx)`]
    // The exception cannot depend on which caller git grep encounters first.
    for (const lines of [[deferred, unflagged], [unflagged, deferred]]) {
      expect(missingRoutes(calledPaths(lines.join("\n")), [])).toEqual(expected)
    }
  })

  it("every /api/v1 path the app calls is registered, or a listed exception", () => {
    const missing = missingRoutes(calledPaths())
    expect(missing).toEqual([])
  })
})
